const ISO_TILT = Math.atan(1 / Math.SQRT2); // 35.264 deg: makes the cube's silhouette a regular hexagon

export type BashLogoProps = LogoProps & {
  /** colour of the embossed "$_" prompt */
  glyphColor?: string;
};

export function BashLogo({
  size = 2,
  color = "#ffffff",
  glyphColor = "#293138",
  bevel = 0.006,
  matte = true,
  metalness = 0.15,
  roughness = 0.4,
  curveSegments = 12,
  // accepted for API parity with the flat logos, a cube has no thickness knob
  thickness: _thickness,
  depth: _depth,
  holeColor: _holeColor,
  ...groupProps
}: BashLogoProps) {
  // iso cube: hexagon height = side * 2 * sqrt(2/3)
  const side = size / (2 * Math.sqrt(2 / 3));
  const glyphHeight = side * 0.5;
  const glyphDepth = side * 0.05;

  const { cube, glyph } = useMemo(() => {
    const radius = Math.max(side * 0.04, bevel * side * 6);
    const cube = new RoundedBoxGeometry(side, side, side, 4, radius);
    const shapes = GLYPH.map((flat) => {
      const pts: THREE.Vector2[] = [];
      for (let i = 0; i < flat.length; i += 2) pts.push(new THREE.Vector2(flat[i] * glyphHeight, flat[i + 1] * glyphHeight));
      return new THREE.Shape(pts);
    });
    const glyph = new THREE.ExtrudeGeometry(shapes, {
      depth: glyphDepth,
      curveSegments,
      bevelEnabled: true,
      bevelThickness: glyphDepth * 0.15,
      bevelSize: glyphHeight * 0.006,
      bevelOffset: -glyphHeight * 0.006,
      bevelSegments: 1,
    });
    return { cube, glyph };
  }, [side, glyphHeight, glyphDepth, bevel, curveSegments]);

  useEffect(
    () => () => {
      cube.dispose();
      glyph.dispose();
    },
    [cube, glyph]
  );

  const material = (c: string) =>
    matte ? (
      <meshLambertMaterial color={c} emissive={c} emissiveIntensity={0.18} />
    ) : (
      <meshStandardMaterial color={c} metalness={metalness} roughness={roughness} />
    );

  return (
    <group {...groupProps}>
      {/* Y first (45deg), then X (35.264deg) => isometric: the +z face becomes the right-hand face */}
      <group rotation={[ISO_TILT, Math.PI / 4, 0]}>
        <mesh geometry={cube} castShadow receiveShadow>
          {material(color)}
        </mesh>
        {/* prompt sits on the +z face, sunk a hair into it so it never z-fights */}
        <mesh geometry={glyph} position={[0, 0, side / 2 - glyphDepth * 0.1]} castShadow receiveShadow>
          {material(glyphColor)}
        </mesh>
      </group>
    </group>
  );
}
